import { test, expect } from '@playwright/test';

test('validates the card number inside the iframe', async ({ page }) => {
  await page.goto('/frames');
  const payment = page.getByTitle('Payment form').contentFrame();
  await payment.getByLabel('Card number').fill('1234');
  await payment.getByRole('button', { name: 'Pay now' }).click();
  await expect(payment.getByRole('status')).toHaveText('Card number must be 16 digits');
});

test('help opens in a new tab', async ({ page, context }) => {
  await page.goto('/newtab');
  const pagePromise = context.waitForEvent('page');
  await page.getByRole('link', { name: 'Open help center' }).click();
  const help = await pagePromise;
  await expect(help.getByRole('heading', { name: 'Help Center' })).toBeVisible();
  expect(context.pages()).toHaveLength(2);
});
